fn solve(n: i8, s: Vec<char>) -> i8 {
    // x > y => Region A, represented by `true`
    // y > x => Region B, represented by `false`
    // x == y => border, represented by `None`
    let mut x = 0i32;
    let mut y = 0i32;
    let mut last_region: Option<bool> = None;
    let mut transitions = 0i8;

    for &mv in &s {
        match mv {
            'U' => y += 1,
            'R' => x += 1,
            _ => {} // by problem statement, s contains only 'U' or 'R'
        }

        // Determine the current region (or border)
        let current_region = if x > y {
            Some(true)
        } else if y > x {
            Some(false)
        } else {
            None
        };

        // If we're strictly in a region (not on the border),
        // and we've been in a different region before,
        // that's a transition.
        if let Some(r) = current_region {
            if let Some(prev) = last_region {
                if prev != r {
                    transitions += 1;
                }
            }
            last_region = Some(r);
        }
        // If we're on the border, do nothing (just keep last_region as is)
    }

    transitions
}